import json,re,pathlib
for p in ['products/research/gumroad-official-pricing.html','products/research/gumroad-official-payouts.html']:
  t=pathlib.Path(p).read_text(errors='replace')
  t=re.sub(r'<script.*?</script>|<style.*?</style>','',t,flags=re.S)
  t=re.sub(r'<[^>]+>',' ',t);t=re.sub(r'\s+',' ',t)
  print('=====',p,len(t))
  for kw in ['%','fee','payout','Payout','PayPal','Canada','country','countries','minimum','Merchant of Record','merchant','tax','weekly','Friday','bank','Stripe','\$10','eligib']:
    for m in list(re.finditer(kw,t))[:3]:
      print(kw,'|',t[max(0,m.start()-160):m.end()+160])
